'use strict';

// MODULES //

var dlamch = require( '@stdlib/lapack/base/dlamch' );
var abs = require( '@stdlib/math/base/special/abs' );


// VARIABLES //

// Safe minimum such that `1/SFMIN` does not overflow:
var SFMIN = dlamch( 'S' );


// MAIN //

/**
* Computes an `LU` factorization of a general M-by-N matrix `A` using partial pivoting with row interchanges.
*
* ## Notes
*
* -   `A` is overwritten by the factors `L` and `U`, where the unit diagonal elements of `L` are not stored.
* -   `IPIV` should have at least `min(M,N)` indexed elements and is overwritten by the pivot indices. Pivot indices are 0-based. For `0 <= i < min(M,N)`, row `i` of the matrix was interchanged with row `IPIV(i)`.
* -   The status code is one-based, meaning that a status code `k` greater than zero indicates that `U(k-1,k-1)` is exactly zero.
*
* @private
* @param {NonNegativeInteger} M - number of rows in `A`
* @param {NonNegativeInteger} N - number of columns in `A`
* @param {Float64Array} A - input matrix
* @param {integer} strideA1 - row stride of `A`
* @param {integer} strideA2 - column stride of `A`
* @param {NonNegativeInteger} offsetA - starting index of `A`
* @param {Int32Array} IPIV - vector of pivot indices
* @param {integer} strideIPIV - stride length for `IPIV`
* @param {NonNegativeInteger} offsetIPIV - starting index of `IPIV`
* @returns {integer} status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 2.0, 1.0, 4.0, 6.0 ] );
* var IPIV = new Int32Array( 2 );
*
* var info = dgetf2( 2, 2, A, 2, 1, 0, IPIV, 1, 0 );
* // info => 0
*/
function dgetf2( M, N, A, strideA1, strideA2, offsetA, IPIV, strideIPIV, offsetIPIV ) { // eslint-disable-line max-len
	var maxVal;
	var minMN;
	var info;
	var temp;
	var val;
	var i0;
	var ia;
	var ib;
	var ic;
	var ij;
	var ip;
	var ir;
	var jp;
	var r;
	var c;
	var j;

	if ( M === 0 || N === 0 ) {
		return 0;
	}
	minMN = ( M < N ) ? M : N;
	info = 0;

	// Index of `A[j,j]`:
	ij = offsetA;

	// Index of `A[j,0]`:
	ir = offsetA;

	// Index of `IPIV[j]`:
	ip = offsetIPIV;

	for ( j = 0; j < minMN; j++ ) {
		// Find the first row `jp` in `j:M-1` containing an element having the maximum absolute value in the j-th column (cf. `idamax`)...
		maxVal = abs( A[ ij ] );
		jp = j;
		i0 = ij;
		ia = ij + strideA1;
		for ( r = j+1; r < M; r++ ) {
			val = abs( A[ ia ] );
			if ( val > maxVal ) {
				maxVal = val;
				jp = r;
				i0 = ia;
			}
			ia += strideA1;
		}
		IPIV[ ip ] = jp;
		ip += strideIPIV;

		// Test for singularity...
		if ( A[ i0 ] !== 0.0 ) {
			// Apply the interchange to columns `0:N-1` (cf. `dswap`)...
			if ( jp !== j ) {
				ia = ir;
				ib = ir + ( ( jp-j ) * strideA1 );
				for ( c = 0; c < N; c++ ) {
					val = A[ ia ];
					A[ ia ] = A[ ib ];
					A[ ib ] = val;
					ia += strideA2;
					ib += strideA2;
				}
			}
			// Compute the elements `j+1:M-1` of the j-th column (cf. `dscal`)...
			if ( j < M-1 ) {
				temp = A[ ij ];
				ia = ij + strideA1;

				// Only scale by the reciprocal of the pivot when the pivot is not less than the safe minimum, as, otherwise, computing the reciprocal may overflow...
				if ( abs( temp ) >= SFMIN ) {
					temp = 1.0 / temp;
					for ( r = j+1; r < M; r++ ) {
						A[ ia ] *= temp;
						ia += strideA1;
					}
				} else {
					for ( r = j+1; r < M; r++ ) {
						A[ ia ] /= temp;
						ia += strideA1;
					}
				}
			}
		} else if ( info === 0 ) {
			// In order to remain consistent with LAPACK, the status code is one-based, meaning that a status code `k` indicates that `U(k-1,k-1)` is exactly zero when using zero-based indexing...
			info = j + 1;
		}
		// Update the trailing submatrix (i.e., rows `j+1:M-1` and columns `j+1:N-1`) (cf. `dger`)...
		if ( j < minMN-1 ) {
			ib = ij + strideA2;
			for ( c = j+1; c < N; c++ ) {
				temp = A[ ib ];
				if ( temp !== 0.0 ) {
					ia = ib + strideA1;
					ic = ij + strideA1;
					for ( r = j+1; r < M; r++ ) {
						A[ ia ] -= A[ ic ] * temp;
						ia += strideA1;
						ic += strideA1;
					}
				}
				ib += strideA2;
			}
		}
		ij += strideA1 + strideA2;
		ir += strideA1;
	}
	return info;
}


// EXPORTS //

module.exports = dgetf2;
